public class TransferFundsOpService {

    private final TransferFundsRequestMapper requestMapper;
    private final TransferFundsResponseMapper responseMapper;
    private final StandardErrorRSFmtMapper errorResponseMapper;

    private final ValidateTransferStep validateTransferStep;
    private final CheckLimitsStep checkLimitsStep;
    private final FraudCheckStep fraudCheckStep;
    private final SkipFraudOnTimeoutStep skipFraudOnTimeoutStep;
    private final ExecuteTransferStep executeTransferStep;

    private final ValidationFailedStep validationFailedStep;
    private final InsufficientFundsStep insufficientFundsStep;
    private final DailyLimitExceededStep dailyLimitExceededStep;
    private final AccountNotEligibleStep accountNotEligibleStep;
    private final FraudSuspectedStep fraudSuspectedStep;
    private final CoreBankingRejectedStep coreBankingRejectedStep;
    private final TransferAlreadyProcessedStep transferAlreadyProcessedStep;
    private final DatabaseErrorStep databaseErrorStep;
    private final TechnicalErrorStep technicalErrorStep;

    public TransferFundsOpService(FraudDetectionServicePort fraudDetectionService) {
        this.requestMapper = new TransferFundsRequestMapper();
        this.responseMapper = new TransferFundsResponseMapper();
        this.errorResponseMapper = new StandardErrorRSFmtMapper();

        this.validateTransferStep = new ValidateTransferStep();
        this.checkLimitsStep = new CheckLimitsStep();
        this.fraudCheckStep = new FraudCheckStep(3000, fraudDetectionService);
        this.skipFraudOnTimeoutStep = new SkipFraudOnTimeoutStep();
        this.executeTransferStep = new ExecuteTransferStep();

        this.validationFailedStep = new ValidationFailedStep();
        this.insufficientFundsStep = new InsufficientFundsStep();
        this.dailyLimitExceededStep = new DailyLimitExceededStep();
        this.accountNotEligibleStep = new AccountNotEligibleStep();
        this.fraudSuspectedStep = new FraudSuspectedStep();
        this.coreBankingRejectedStep = new CoreBankingRejectedStep();
        this.transferAlreadyProcessedStep = new TransferAlreadyProcessedStep();
        this.databaseErrorStep = new DatabaseErrorStep();
        this.technicalErrorStep = new TechnicalErrorStep();
    }

    public String execute(String requestXml) throws Exception {
        TransferFundsRequestXml reqXml = parseRequestXml(requestXml);
        TransferFundsRequestBusiness reqBiz = requestMapper.toBusinessInput(reqXml);

        Map<String, Object> context = new HashMap<>();
        context.put("CHANNEL_ID", "INTERNET");
        context.put("MAX_RETRY", "3");
        context.put("TransferStatus", "PENDING");
        context.put("FraudScore", "0");

        if (reqBiz != null) {
            context.put("SourceAccount", reqBiz.getSourceAccount());
            context.put("TargetAccount", reqBiz.getTargetAccount());
            context.put("Amount", reqBiz.getAmount());
            context.put("Currency", reqBiz.getCurrency());
            context.put("SessionToken", reqBiz.getSessionToken());
            context.put("TransferReference", reqBiz.getTransferReference());
            context.put("ScheduledDate", reqBiz.getScheduledDate());
        }

        String currentStep = "ValidateTransfer";
        int rc = 0;
        boolean errorBodySwitched = false;
        Object activeErrorStep = null;

        while (currentStep != null && !currentStep.equals("end")) {
            switch (currentStep) {
                case "ValidateTransfer":
                    rc = validateTransferStep.execute(context);
                    if (rc == 0) {
                        currentStep = "CheckLimits";
                    } else {
                        currentStep = "ValidationFailed";
                    }
                    break;

                case "CheckLimits":
                    rc = checkLimitsStep.execute(context);
                    if (rc == 0) {
                        currentStep = "FraudCheck";
                    } else if (rc == 3) {
                        currentStep = "DailyLimitExceeded";
                    } else if (rc == 4) {
                        currentStep = "InsufficientFunds";
                    } else if (rc == 5) {
                        currentStep = "AccountNotEligible";
                    } else if (rc == 8) {
                        currentStep = "DatabaseError";
                    } else {
                        currentStep = "TechnicalError";
                    }
                    break;

                case "FraudCheck":
                    try {
                        rc = fraudCheckStep.execute(context);
                    } catch (TimeoutException te) {
                        rc = -99;
                    } catch (Exception e) {
                        rc = 8;
                    }
                    if (rc == -99) {
                        currentStep = "SkipFraudOnTimeout";
                    } else if (rc == 0) {
                        currentStep = "ExecuteTransfer";
                    } else if (rc == 2) {
                        currentStep = "FraudSuspected";
                    } else {
                        currentStep = "TechnicalError";
                    }
                    break;

                case "SkipFraudOnTimeout":
                    try {
                        rc = skipFraudOnTimeoutStep.execute(context);
                    } catch (Exception e) {
                        rc = 1;
                    }
                    if (rc == 0) {
                        currentStep = "ExecuteTransfer";
                    } else {
                        currentStep = "TechnicalError";
                    }
                    break;

                case "ExecuteTransfer":
                    rc = executeTransferStep.execute(context);
                    if (rc == 0) {
                        currentStep = "end";
                    } else if (rc == 6) {
                        currentStep = "CoreBankingRejected";
                    } else if (rc == 7) {
                        currentStep = "TransferAlreadyProcessed";
                    } else if (rc == 8) {
                        currentStep = "DatabaseError";
                    } else {
                        currentStep = "TechnicalError";
                    }
                    break;

                case "ValidationFailed":
                    validationFailedStep.execute(context);
                    activeErrorStep = validationFailedStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "InsufficientFunds":
                    insufficientFundsStep.execute(context);
                    activeErrorStep = insufficientFundsStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "DailyLimitExceeded":
                    dailyLimitExceededStep.execute(context);
                    activeErrorStep = dailyLimitExceededStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "AccountNotEligible":
                    accountNotEligibleStep.execute(context);
                    activeErrorStep = accountNotEligibleStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "FraudSuspected":
                    fraudSuspectedStep.execute(context);
                    activeErrorStep = fraudSuspectedStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "CoreBankingRejected":
                    coreBankingRejectedStep.execute(context);
                    activeErrorStep = coreBankingRejectedStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "TransferAlreadyProcessed":
                    transferAlreadyProcessedStep.execute(context);
                    activeErrorStep = transferAlreadyProcessedStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "DatabaseError":
                    databaseErrorStep.execute(context);
                    activeErrorStep = databaseErrorStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                case "TechnicalError":
                    technicalErrorStep.execute(context);
                    activeErrorStep = technicalErrorStep;
                    errorBodySwitched = true;
                    currentStep = "end";
                    break;

                default:
                    currentStep = "end";
                    break;
            }
        }

        if (errorBodySwitched && activeErrorStep != null) {
            ErrorReply errorReply = new ErrorReply();
            if (activeErrorStep instanceof ValidationFailedStep) {
                errorReply.setErrorCategory((String) context.get("ErrorCategory"));
                errorReply.setErrorNumber((String) context.get("ErrorNumber"));
                errorReply.setErrorDescription((String) context.get("ErrorDescription"));
            } else {
                try {
                    java.lang.reflect.Method catMethod = activeErrorStep.getClass().getMethod("getErrorCategory");
                    java.lang.reflect.Method numMethod = activeErrorStep.getClass().getMethod("getErrorNumber");
                    errorReply.setErrorCategory((String) catMethod.invoke(activeErrorStep));
                    errorReply.setErrorNumber((String) numMethod.invoke(activeErrorStep));
                } catch (Exception e) {
                    errorReply.setErrorCategory("ERROR");
                    errorReply.setErrorNumber("999");
                }
                errorReply.setErrorDescription((String) context.get("ErrorDescription"));
            }
            errorReply.setRequestId((String) context.get("RequestId"));
            return errorResponseMapper.format(errorReply);
        } else {
            TransferFundsResponseBusiness respBiz = new TransferFundsResponseBusiness();
            respBiz.setTransferId((String) context.get("TransferId"));
            respBiz.setTransferStatus((String) context.get("TransferStatus"));
            if (context.get("ExecutionDate") instanceof java.util.Date) {
                respBiz.setExecutionDate((java.util.Date) context.get("ExecutionDate"));
            }
            if (context.get("ExecutionTime") instanceof String) {
                try {
                    respBiz.setExecutionTime(new java.text.SimpleDateFormat("HH:mm:ss").parse((String) context.get("ExecutionTime")));
                } catch (Exception ignored) {}
            } else if (context.get("ExecutionTime") instanceof java.util.Date) {
                respBiz.setExecutionTime((java.util.Date) context.get("ExecutionTime"));
            }
            respBiz.setAmount((BigDecimal) context.get("Amount"));
            respBiz.setCurrency((String) context.get("Currency"));
            respBiz.setSourceAccount((String) context.get("SourceAccount"));
            respBiz.setTargetAccount((String) context.get("TargetAccount"));
            respBiz.setNewSourceBalance((BigDecimal) context.get("NewSourceBalance"));
            Object fcs = context.get("FraudCheckSkipped");
            if (fcs instanceof Boolean) {
                respBiz.setFraudCheckSkipped((Boolean) fcs);
            }
            return responseMapper.format(respBiz);
        }
    }

    private TransferFundsRequestXml parseRequestXml(String xml) {
        try {
            com.fasterxml.jackson.dataformat.xml.XmlMapper xmlMapper = new com.fasterxml.jackson.dataformat.xml.XmlMapper();
            return xmlMapper.readValue(xml, TransferFundsRequestXml.class);
        } catch (Exception e) {
            TransferFundsRequestXml fallback = new TransferFundsRequestXml();
            return fallback;
        }
    }
}

